(function(){
"use strict";
var URLS={config:"data/power-family-intelligence-layer.json",families:"data/behind-the-curtain-family-access.json",people:"data/behind-the-curtain-people-registry.json",core:"data/behind-the-curtain.json"};
var state={config:null,families:[],people:[],core:null,links:[],sourceCount:0,watch:new Set(JSON.parse(localStorage.getItem("pfWatchlist")||"[]")),watchOnly:false,filters:{q:"",family:"",vector:"",evidence:""}};
var $=function(s,r){return (r||document).querySelector(s)}, $$=function(s,r){return Array.from((r||document).querySelectorAll(s))};
function esc(v){return String(v==null?"":v).replace(/[&<>"']/g,function(c){return({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"})[c]})}
function slug(v){return String(v||"").toLowerCase().replace(/[^a-z0-9]+/g,"_").replace(/^_|_$/g,"")}
function clamp(n,a,b){return Math.max(a,Math.min(b,Number(n)||0))}
function badge(c){return '<span class="pf-badge '+esc(slug(c))+'">'+esc(label(c))+'</span>'}
function label(c){var hit=(state.config.claimClasses||[]).find(function(x){return x.id===c});return hit?hit.label:String(c||"Unclassified").replace(/_/g," ")}
function avg(a){return a.length?a.reduce(function(x,y){return x+y},0)/a.length:0}
function pct5(n){return Math.round(clamp(n,0,5)*20)}
function to5(n){return Math.round(clamp((Number(n)||0)/20,0,5)*10)/10}
function tier(person,id){var a=(person.tierAccess||[]).filter(function(x){return !id||x.tierId===id});return a.length?Math.max.apply(null,a.map(function(x){return Number(x.score)||0})):0}
function vectorFor(person){var out=[];(person.tierAccess||[]).forEach(function(t){var id=t.tierId||"";if(id.indexOf("money")>=0)out.push("Asset management");if(id.indexOf("intelligence")>=0)out.push("Intelligence");if(id.indexOf("policy")>=0)out.push("Think tanks");if(id.indexOf("technology")>=0)out.push("Technology");if(id.indexOf("media")>=0)out.push("Media");if(id.indexOf("public")>=0)out.push("Government");if(id.indexOf("permanent")>=0)out.push("International organisations")});return Array.from(new Set(out))}
function linkForPerson(id){return state.links.find(function(x){return x.personId===id})}
function familyForPerson(p){var link=linkForPerson(p.id);return link?state.families.find(function(f){return f.id===link.familyId}):null}
function scores(p){var family=familyForPerson(p), dims=family&&family.dimensions||{};return{
institutionalAuthority:to5(Math.max(tier(p,"public-stage"),tier(p,"permanent-system"),p.crossSystemScore||0)),
assetControl:to5(Math.max(tier(p,"money-gatekeepers"),dims.votingOrOwnershipControl||0,dims.capitalAccess||0)),
governmentAccess:to5(Math.max(tier(p,"public-stage"),dims.formalAuthority||0,dims.appointmentPower||0)),
networkCentrality:to5(Math.max(p.crossSystemScore||0,(p.tierAccess||[]).length*22,dims.crossSectorReach||0)),
informationAccess:to5(Math.max(tier(p,"intelligence-security"),tier(p,"policy-architects"),tier(p,"technology-data"))),
intergenerationalPosition:linkForPerson(p.id)?(linkForPerson(p.id).successionStatus==="active_successor"?5:4):to5(dims.institutionalContinuity||0),
operationalActivity:to5(Math.max.apply(null,[0].concat((p.tierAccess||[]).map(function(x){return x.score||0})))),
evidenceStrength:p.confidence==="very_high"?5:p.confidence==="high"?4.5:p.confidence==="moderate"?3.5:2.5}}
function totalScore(p){var s=scores(p);return Math.round(avg(Object.keys(s).map(function(k){return s[k]}))*20*10)/10}
function mechanismCount(p){return new Set((p.tierAccess||[]).map(function(x){return x.tierId})).size}
function roleText(p){return (p.currentRole||"")+" "+(p.organization||"")}
function isGatekeeper(p){var t=roleText(p).toLowerCase();return state.config.gatekeeperKeywords.some(function(k){return t.indexOf(k)>=0})&&tier(p,"public-stage")<95}
function publicScore(p){return tier(p,"public-stage")}
function operatorScore(p){return Math.max(tier(p,"money-gatekeepers"),tier(p,"permanent-system"),tier(p,"policy-architects"),tier(p,"intelligence-security"),tier(p,"technology-data"))}
function sourceIdsFor(item){return item&&item.sourceIds||[]}
function allSourceIds(){var s=new Set();state.families.forEach(function(x){sourceIdsFor(x).forEach(function(y){s.add(y)})});state.people.forEach(function(x){sourceIdsFor(x).forEach(function(y){s.add(y)})});return s}
function matches(p){var q=state.filters.q.toLowerCase(), fam=familyForPerson(p), vectors=vectorFor(p);if(state.watchOnly&&!state.watch.has("person:"+p.id))return false;if(state.filters.family&&(!fam||fam.id!==state.filters.family))return false;if(state.filters.vector&&vectors.indexOf(state.filters.vector)<0)return false;if(state.filters.evidence&&p.classification!==state.filters.evidence)return false;if(q&&[p.name,p.currentRole,p.organization,(p.jurisdictions||[]).join(" "),fam&&fam.name,vectors.join(" ")].join(" ").toLowerCase().indexOf(q)<0)return false;return true}
function toast(msg){var e=$("#pf-toast");e.textContent=msg;e.classList.add("show");clearTimeout(toast.t);toast.t=setTimeout(function(){e.classList.remove("show")},1800)}
function toggleWatch(key){if(state.watch.has(key))state.watch.delete(key);else state.watch.add(key);localStorage.setItem("pfWatchlist",JSON.stringify(Array.from(state.watch)));toast(state.watch.has(key)?"Added to watchlist":"Removed from watchlist");renderAll()}
function bars(p){var s=scores(p);return '<div class="pf-bars">'+Object.keys(s).map(function(k){return '<div class="pf-bar">'+esc((state.config.scoreDimensions.find(function(d){return d.id===k})||{label:k}).label)+' · '+s[k]+'/5<i style="--v:'+pct5(s[k])+'%"></i></div>'}).join("")+'</div>'}
function personCard(p,rank){var f=familyForPerson(p), vectors=vectorFor(p), score=totalScore(p);return '<article class="pf-card" data-person="'+esc(p.id)+'"><div class="pf-card-head"><div class="pf-rank">'+(rank?rank:"◆")+'</div><div><div class="pf-meta">'+badge(p.classification)+(f?'<span class="pf-tag">'+esc(f.name)+'</span>':"")+'</div><h3>'+esc(p.name)+'</h3><p>'+esc(p.currentRole||"Role under review")+'</p></div><div class="pf-score">'+score+'<small>/100</small></div></div><div class="pf-tags">'+vectors.map(function(v){return '<span class="pf-tag">'+esc(v)+'</span>'}).join("")+'</div>'+bars(p)+'<div class="pf-card-actions"><button type="button" data-open-person="'+esc(p.id)+'">Open full profile</button><button type="button" data-watch="person:'+esc(p.id)+'">'+(state.watch.has("person:"+p.id)?"Watching":"Track person")+'</button></div></article>'}
function familyCard(f){var linked=state.links.filter(function(l){return l.familyId===f.id}).map(function(l){return state.people.find(function(p){return p.id===l.personId})}).filter(Boolean);var dims=f.dimensions||{};return '<article class="pf-family" data-family="'+esc(f.id)+'"><div class="pf-card-head"><div class="pf-rank">'+esc(f.rank||"◆")+'</div><div><div class="pf-meta">'+badge(f.classification)+'<span class="pf-tag">'+esc(f.type||"Family network")+'</span></div><h3>'+esc(f.name)+'</h3><p>'+esc((f.jurisdictions||[]).join(" · "))+'</p></div><div class="pf-score">'+esc(f.accessScore||"—")+'<small>/100</small></div></div><div class="pf-dimensions">'+Object.keys(dims).map(function(k){return '<div class="pf-dimension">'+esc(k.replace(/([A-Z])/g," $1"))+'<i style="--v:'+clamp(dims[k],0,100)+'%"></i></div>'}).join("")+'</div><details><summary>Documented access, constraints and linked people</summary><h4>Documented access</h4><ul>'+((f.documentedAccess||[]).map(function(x){return '<li>'+esc(x)+'</li>'}).join("")||"<li>Evidence profile under expansion.</li>")+'</ul><h4>Structures reached</h4><p>'+esc((f.structuresReached||[]).join(" · "))+'</p><h4>Constraints</h4><ul>'+((f.constraints||[]).map(function(x){return '<li>'+esc(x)+'</li>'}).join(""))+'</ul><h4>Not established</h4><p>'+esc(f.unsupportedClaim||"No unsupported claim recorded.")+'</p><h4>Living profiles</h4><div class="pf-card-actions">'+(linked.length?linked.map(function(p){return '<button data-open-person="'+esc(p.id)+'">'+esc(p.name)+'</button>'}).join(""):'<span class="muted">No verified living profile linked yet. This remains a research gap.</span>')+'</div></details><div class="pf-card-actions"><button data-watch="family:'+esc(f.id)+'">'+(state.watch.has("family:"+f.id)?"Watching":"Track family")+'</button></div></article>'}
function openPerson(id){var p=state.people.find(function(x){return x.id===id});if(!p)return;var f=familyForPerson(p), s=scores(p), link=linkForPerson(p.id);var content='<h2 id="pf-modal-title">'+esc(p.name)+'</h2><p class="muted">'+esc(p.currentRole||"")+' · '+esc(p.organization||"")+'</p><div class="pf-meta">'+badge(p.classification)+'<span class="pf-tag">'+esc(p.confidence||"confidence not set")+'</span>'+(f?'<span class="pf-tag">'+esc(f.name)+'</span>':"")+'</div><div class="pf-profile-grid"><section class="pf-profile-block"><h4>Identity and current role</h4><p><strong>Jurisdiction:</strong> '+esc((p.jurisdictions||[]).join(", "))+'</p><p><strong>Status:</strong> '+esc(p.status||"under review")+'</p><p><strong>Last verified:</strong> '+esc(p.verifiedAt||"not recorded")+'</p><p><strong>Next review:</strong> '+esc(p.nextReviewDue||"not scheduled")+'</p></section><section class="pf-profile-block"><h4>Family or continuity link</h4><p>'+(link?esc(link.relationship):"No family link is asserted by this layer.")+'</p><p><strong>Succession status:</strong> '+esc(link&&link.successionStatus||"not applicable")+'</p></section><section class="pf-profile-block"><h4>Documented access points</h4><ul>'+((p.accessToPower||[]).map(function(x){return "<li>"+esc(x)+"</li>"}).join("")||"<li>No access mechanism recorded.</li>")+'</ul></section><section class="pf-profile-block"><h4>Documented exercise and role mechanisms</h4><ul>'+((p.tierAccess||[]).map(function(x){return "<li><strong>"+esc(x.mechanism||x.tierId)+":</strong> "+esc(x.basis||"")+"</li>"}).join("")||"<li>No decision mechanism recorded.</li>")+'</ul></section><section class="pf-profile-block"><h4>Constraints and counterweight</h4><ul>'+((p.constraints||[]).map(function(x){return "<li>"+esc(x)+"</li>"}).join("")||"<li>Constraints not yet recorded.</li>")+'</ul></section><section class="pf-profile-block"><h4>Evidence boundary</h4><p>'+esc(p.notEstablished||"No additional boundary statement recorded.")+'</p><p><strong>Source IDs:</strong> '+esc(sourceIdsFor(p).join(", ")||"none")+'</p></section></div><h3>Proximity-to-Power Assessment</h3>'+bars(p)+'<div class="pf-card-actions"><button data-watch="person:'+esc(p.id)+'">'+(state.watch.has("person:"+p.id)?"Remove from watchlist":"Track this person")+'</button><a href="contact-the-machine.html?topic=correction&subject='+encodeURIComponent(p.name)+'">Correction / right of reply</a></div>';$("#pf-modal-content").innerHTML=content;$("#pf-modal").classList.add("open");$("#pf-modal").setAttribute("aria-hidden","false")}
function closeModal(){$("#pf-modal").classList.remove("open");$("#pf-modal").setAttribute("aria-hidden","true")}
function renderRanked(id,list,n){var el=$(id);var filtered=list.filter(matches).slice(0,n||8);el.innerHTML=filtered.length?filtered.map(function(p,i){return personCard(p,i+1)}).join(""):'<div class="pf-empty">No verified profiles match the current filter.</div>'}
function renderLanes(){$("#pf-lanes").innerHTML=state.config.lanes.map(function(x){return '<article class="pf-lane"><h3>'+esc(x.title)+'</h3><p>'+esc(x.text)+'</p></article>'}).join("")}
function renderDirectory(){var q=state.filters.q.toLowerCase();var items=state.families.filter(function(f){if(state.watchOnly&&!state.watch.has("family:"+f.id))return false;if(state.filters.family&&f.id!==state.filters.family)return false;if(state.filters.evidence&&f.classification!==state.filters.evidence)return false;if(q&&[f.name,f.type,(f.jurisdictions||[]).join(" "),(f.structuresReached||[]).join(" ")].join(" ").toLowerCase().indexOf(q)<0)return false;return true});$("#pf-family-directory").innerHTML=items.length?items.map(familyCard).join(""):'<div class="pf-empty">No family records match the current filter.</div>'}
function renderComparisons(){var faces=state.people.slice().sort(function(a,b){return publicScore(b)-publicScore(a)}).filter(matches).slice(0,5), ops=state.people.slice().sort(function(a,b){return operatorScore(b)-operatorScore(a)}).filter(matches).slice(0,5);$("#pf-faces-operators").innerHTML='<div class="pf-comparison-col"><h3>Public faces</h3>'+faces.map(function(p,i){return personCard(p,i+1)}).join("")+'</div><div class="pf-versus">VERSUS</div><div class="pf-comparison-col"><h3>Operational access</h3>'+ops.map(function(p,i){return personCard(p,i+1)}).join("")+'</div>'}
function renderGaps(){var items=state.families.slice(0,12).map(function(f){return {title:f.name,text:(f.constraints||[]).join(" · ")||"Control-chain documentation remains incomplete.",not:f.unsupportedClaim||""}});$("#pf-gaps").innerHTML=items.map(function(x){return '<article class="pf-card"><h3>'+esc(x.title)+'</h3><p>'+esc(x.text)+'</p><div class="pf-boundary"><strong>Do not infer:</strong> '+esc(x.not)+'</div></article>'}).join("")}
function renderClaims(){$("#pf-claims").innerHTML=state.config.claims.map(function(c){return '<article class="pf-card"><div class="pf-meta">'+badge(c.classification)+'<span class="pf-tag">'+esc(c.confidence)+' confidence</span></div><h3>'+esc(c.claim)+'</h3><details open><summary>Evidence test</summary><p><strong>Supporting evidence:</strong> '+esc(c.support)+'</p><p><strong>Evidence against:</strong> '+esc(c.against)+'</p><p><strong>Missing evidence:</strong> '+esc(c.missing)+'</p><p><strong>Current conclusion:</strong> '+esc(c.conclusion)+'</p></details></article>'}).join("")}
function renderQuestions(){$("#pf-questions").innerHTML=state.config.unresolvedQuestions.map(function(q,i){var key="question:"+i;return '<article class="pf-question"><strong>Q'+(i+1)+'</strong><p>'+esc(q)+'</p><div class="pf-card-actions"><button data-watch="'+key+'">'+(state.watch.has(key)?"Following":"Follow question")+'</button><a href="contact-the-machine.html?topic=evidence&question='+encodeURIComponent(q)+'">Drop evidence</a></div></article>'}).join("")}
function renderMap(){var people=state.people.slice().sort(function(a,b){return totalScore(b)-totalScore(a)}).filter(matches).slice(0,18);var families=state.families.filter(function(f){return people.some(function(p){var x=familyForPerson(p);return x&&x.id===f.id})}).slice(0,8);var W=900,H=640,cx=W/2,cy=H/2, nodes=[], edges=[];families.forEach(function(f,i){var a=(Math.PI*2*i/Math.max(families.length,1))-Math.PI/2;nodes.push({id:"family:"+f.id,label:f.name,x:cx+Math.cos(a)*255,y:cy+Math.sin(a)*235,type:"family",data:f})});people.forEach(function(p,i){var a=(Math.PI*2*i/Math.max(people.length,1))-Math.PI/2;var r=110+(i%2)*55;nodes.push({id:"person:"+p.id,label:p.name,x:cx+Math.cos(a)*r,y:cy+Math.sin(a)*r,type:"person",data:p});var f=familyForPerson(p);if(f)edges.push({a:"family:"+f.id,b:"person:"+p.id,type:"documented"})});var byId={};nodes.forEach(function(n){byId[n.id]=n});var svg='<svg viewBox="0 0 '+W+' '+H+'" role="img" aria-label="Power-family network map"><g>'+edges.map(function(e){var a=byId[e.a],b=byId[e.b];return a&&b?'<line class="pf-edge '+esc(e.type)+'" x1="'+a.x+'" y1="'+a.y+'" x2="'+b.x+'" y2="'+b.y+'"/>':""}).join("")+'</g><g>'+nodes.map(function(n){return '<g class="pf-node '+n.type+'" data-map-node="'+esc(n.id)+'" transform="translate('+n.x+' '+n.y+')"><circle r="'+(n.type==="family"?28:20)+'"></circle><text y="'+(n.type==="family"?42:34)+'">'+esc(n.label.length>24?n.label.slice(0,22)+"…":n.label)+'</text></g>'}).join("")+'</g></svg>';$("#pf-map").innerHTML=svg}
function renderMapDetail(key){var parts=key.split(":"),type=parts.shift(),id=parts.join(":");if(type==="person"){var p=state.people.find(function(x){return x.id===id});if(!p)return;$("#pf-map-detail").innerHTML='<div class="pf-meta">'+badge(p.classification)+'</div><h3>'+esc(p.name)+'</h3><p>'+esc(p.currentRole||"")+'</p>'+bars(p)+'<div class="pf-card-actions"><button data-open-person="'+esc(p.id)+'">Open full profile</button></div>'}else{var f=state.families.find(function(x){return x.id===id});if(!f)return;$("#pf-map-detail").innerHTML='<div class="pf-meta">'+badge(f.classification)+'</div><h3>'+esc(f.name)+'</h3><p>'+esc(f.type||"")+'</p><p><strong>Structures reached:</strong> '+esc((f.structuresReached||[]).join(" · "))+'</p><div class="pf-card-actions"><button data-watch="family:'+esc(f.id)+'">'+(state.watch.has("family:"+f.id)?"Watching":"Track family")+'</button></div>'}}
function renderFilters(){var fam=$("#pf-family-filter");fam.innerHTML='<option value="">All families</option>'+state.families.map(function(f){return '<option value="'+esc(f.id)+'">'+esc(f.name)+'</option>'}).join("");var vec=$("#pf-vector-filter");vec.innerHTML='<option value="">All power vectors</option>'+state.config.powerVectors.map(function(v){return '<option>'+esc(v)+'</option>'}).join("");var ev=$("#pf-evidence-filter");var values=Array.from(new Set(state.people.map(function(p){return p.classification}).concat(state.families.map(function(f){return f.classification})))).filter(Boolean);ev.innerHTML='<option value="">All evidence classes</option>'+values.map(function(v){return '<option value="'+esc(v)+'">'+esc(label(v))+'</option>'}).join("")}
function renderAll(){var people=state.people.slice();renderRanked("#pf-institutional",people.sort(function(a,b){return Math.max(publicScore(b),tier(b,"permanent-system"))-Math.max(publicScore(a),tier(a,"permanent-system"))}),8);renderRanked("#pf-capital",state.people.slice().sort(function(a,b){return Math.max(tier(b,"money-gatekeepers"),scores(b).assetControl*20)-Math.max(tier(a,"money-gatekeepers"),scores(a).assetControl*20)}),8);renderRanked("#pf-connectors",state.people.slice().sort(function(a,b){return (mechanismCount(b)*20+(b.crossSystemScore||0))-(mechanismCount(a)*20+(a.crossSystemScore||0))}),8);renderRanked("#pf-gatekeepers",state.people.filter(isGatekeeper).sort(function(a,b){return operatorScore(b)-operatorScore(a)}),8);var successors=state.people.filter(function(p){var l=linkForPerson(p.id);return l&&state.config.successorStatuses.indexOf(l.successionStatus)>=0}).sort(function(a,b){return totalScore(b)-totalScore(a)});renderRanked("#pf-successors",successors,12);renderComparisons();renderDirectory();renderGaps();renderClaims();renderQuestions();renderMap();$("#pf-watchlist-toggle").setAttribute("aria-pressed",String(state.watchOnly))}
function bind(){document.addEventListener("click",function(e){var open=e.target.closest("[data-open-person]");if(open){openPerson(open.getAttribute("data-open-person"));return}var watch=e.target.closest("[data-watch]");if(watch){toggleWatch(watch.getAttribute("data-watch"));return}var node=e.target.closest("[data-map-node]");if(node){renderMapDetail(node.getAttribute("data-map-node"));return}});$("#pf-modal-close").addEventListener("click",closeModal);$("#pf-modal").addEventListener("click",function(e){if(e.target===this)closeModal()});$("#pf-search").addEventListener("input",function(){state.filters.q=this.value;renderAll()});$("#pf-family-filter").addEventListener("change",function(){state.filters.family=this.value;renderAll()});$("#pf-vector-filter").addEventListener("change",function(){state.filters.vector=this.value;renderAll()});$("#pf-evidence-filter").addEventListener("change",function(){state.filters.evidence=this.value;renderAll()});$("#pf-watchlist-toggle").addEventListener("click",function(){state.watchOnly=!state.watchOnly;renderAll()})}
function normalize(){state.links=state.config.familyPersonLinks.filter(function(l){return state.families.some(function(f){return f.id===l.familyId})&&state.people.some(function(p){return p.id===l.personId})});state.sourceCount=allSourceIds().size}
function stats(){document.getElementById("pf-family-count").textContent=state.families.length;document.getElementById("pf-person-count").textContent=state.people.length;document.getElementById("pf-source-count").textContent=state.sourceCount;var dates=[state.core&&state.core.asOf,state.people[0]&&state.people[0].verifiedAt].filter(Boolean).sort();document.getElementById("pf-asof").textContent=dates.pop()||"Under review"}
Promise.all(Object.keys(URLS).map(function(k){return fetch(URLS[k],{cache:"no-store"}).then(function(r){if(!r.ok)throw new Error(k+" feed "+r.status);return r.json()}).then(function(v){return[k,v]})})).then(function(rows){var d={};rows.forEach(function(x){d[x[0]]=x[1]});state.config=d.config;state.families=d.families.families||[];state.people=d.people.people||[];state.core=d.core;normalize();renderLanes();renderFilters();stats();bind();renderAll()}).catch(function(err){console.error(err);document.querySelector("main").insertAdjacentHTML("afterbegin",'<section class="pf-section"><div class="wrap pf-fail"><h2>Power-family intelligence feed unavailable</h2><p>'+esc(err.message)+'</p><p>The page fails closed rather than inventing names, scores or relationships.</p></div></section>')})
})();
